104.2.1 AR(p) model formulation

y_t \quad t\in \{1,2,\ldots,T\} \qquad
  \begin{cases}  
    T&gt;p   \\
    T=n+p \\
    n&gt;1
  \end{cases}

AR(p)

\begin{aligned}
y_t = \sum_{j=1}^p \phi_j y_{t-j} + \underbrace {\varepsilon_t}_{\text{innovations}}
\qquad
  \begin{cases}
    \varepsilon_t \perp y_\tau\ & \forall \tau &lt; t \\
    \varepsilon_t \stackrel{iid}{\sim} \mathcal{N}(0,\nu)
  \end{cases}
\end{aligned}
\tag{104.1}

\begin{aligned}
y_t &= \sum_{j=1}^p \phi_j y_{t-j} +  {\varepsilon_t} & (\text{ normality of innovation})\\
    &= \sum_{j=1}^p \phi_j y_{t-j} +  \mathcal N(0,\nu) & (\text{linearity}) \\
    &= \mathcal{N}(\sum_{j=1}^p \phi_j y_{t-j},\nu) & (\text{rewrite using design matrix})\\
    &= \mathcal{N}(f_t \mathbf {\phi},\nu) \\
\end{aligned}


\begin{aligned}
\mathbb{P}r(y_{1:T}\mid \phi_1, \ldots, \phi_p, \nu )
&= \mathbb{P}r(y_{p+1:T})\prod_{t=p+1}^T \mathbb{P}r(y_t \mid y_{t-1},\ldots,y_{t-p},\phi_1,\ldots,\phi_p,\nu) \\
&= \prod_{t=p+1}^T \mathcal{N}(f_t\phi,\nu) \\
&= \mathcal{N}(F^\top \mathbf{\phi},\nu\mathbb{I}_n) \\
\end{aligned}
\tag{104.2}

where

\mathbf{\phi}=(\phi_1,\ldots,\phi_p)^\top is the vector of parameters, and
\nu is the scale parameter. and
F is the design matrix



F= \begin{pmatrix}
y_{p} & y_{p+1} & \cdots & y_{T-1} \\
y_{p-1} & y_{p} & \cdots & y_{T-2} \\
\vdots & \vdots & \vdots & \ddots & \vdots \\
y_{1} & y_{2} & \cdots & y_{T-p}
\end{pmatrix}
\tag{104.3}



104.2.2 Multiple Linear regression model formulation

y=(y_{p+1},\ldots,y_T) \in \mathbb{R}^n


y = F^\top \mathbf{\phi} + \varepsilon \qquad \varepsilon \sim \mathcal{N}(0,\nu\mathbb{I}_n)


\mathbb{P}r(y \mid \mathbf{\phi},\nu) = \mathcal{N}(F^\top \mathbf{\phi},\nu\mathbb{I}_n)


\mathbf{y}\sim \mathcal{N}(\mathbf{F}^\top \mathbf{\phi},\nu\mathbf{I}_n),\quad \mathbf{\phi}\sim \mathcal{N}(\mathbf{m}_0,\nu\mathbf{C}_0),\quad \nu\sim IG(\frac{n_0}{2},\frac{d_0}{2})
\tag{104.4}
where:






