m = 50; b = 2; k = 4; % Specify physical constants

A = [0 1; -k/m -b/m]; % Continuous-time model
B = [0; 1/m];
C = [1 0]; D = 0;

dT = 0.1; % Sampling period

Ad = expm(A*dT);
Bd = inv(A)*(Ad - eye(2))*B;
Cd = C; Dd = D;

Sw = 0.01; Sv = 1e-5; % Noise parameters
Bw = B;

Z = [-A Bw*Sw*Bw';
     zeros(2) A'];

Cexp = expm(Z*dT);
c12 = Cexp(1:2, 3:4);
c22 = Cexp(3:4, 3:4);

SigmaW = c22' * c12; % Process noise covariance
SigmaV = Sv / dT;    % Measurement noise covariance

142.4 KF Step 1 (Prediction)
% Load data from simulation of system dynamic model
load simOut.mat Ad Bd Cd Dd SigmaV SigmaW dT t u x z

% Determine number of states and timesteps
[nx,nt] = size(x);

% Initialize state estimate and covariance
xhat = zeros(nx,1); 
SigmaX = zeros(nx,nx);

% Initialize storage for state/bounds for plotting purposes
xhatstore = zeros(nx,nt); 
boundstore = zeros(nx,nt);

for k = 2:length(t)

  % KF Step 1a: State prediction time update
  xhat = Ad*xhat + Bd*u(:,k-1); % use prior value of "u"

  % KF Step 1b: Prediction-error covariance time update
  SigmaX = Ad*SigmaX*Ad' + SigmaW;

  % KF Step 1c: Predict system output
  zhat = Cd*xhat + Dd*u(:,k); % use present value of "u"

142.5 KF Step 2 (Correction)
  % KF Step 2a: Compute estimator matrix
  L = SigmaX*Cd'/(Cd*SigmaX*Cd' + SigmaV);

  % KF Step 2b: State estimate measurement update
  xhat = xhat + L*(z(:,k) - zhat);

  % KF Step 2c: Estimation-error covariance measurement update
  SigmaX = (eye(nx) - L*Cd)*SigmaX;

  % Store estimate and bounds for evaluation / plotting purposes
  xhatstore(:,k) = xhat;
  boundstore(:,k) = 3*sqrt(diag(SigmaX));

end

That’s it! We’re now ready to plot results.

142.6 Plot Results from KF Execution
figure(1); clf; % Plot the states and estimates

t2 = [t fliplr(t)]; % Prepare for plotting bounds via "fill"
x2 = [xhatstore - boundstore fliplr(xhatstore + boundstore)];

h1 = fill(t2,x2,'b','FaceAlpha',0.5,'LineStyle','none'); 
hold on; grid on

h2 = plot(t,x',t,xhatstore','--'); % Plot true state and estimate

legend([h2;h1], ...
  'True position','True velocity','Position estimate', ...
  'Velocity estimate','Bounds');

title('Demonstration of Kalman filter state estimates');
xlabel('Time (s)'); 
ylabel('State (m or m/s)');

figure(2); clf;

xerr = x - xhatstore; % Plot state-estimation errors

for k = 1:nx
  subplot(nx,1,k);

  fill(t2,[-boundstore(k,:) fliplr(boundstore(k,:))],'b', ...
       'FaceAlpha',0.25,'LineStyle','none'); 
  hold on; grid on;

  plot(t,xerr(k,:),'b');

  title(sprintf('State %d estimation error with bounds',k));
  xlabel('Time (s)'); 
  ylabel('Error');
end

143.4 What if the KF is poorly initialized?

How well does the KF perform if we don’t know x_0 exactly?
Lesson 1.4.2 simulated the spring-mass-damper system with a true initial state x_0 = 0.
Lesson 1.4.3 initialized the KF with \hat{x}_0^+ = 0 and \Sigma_{x,0}^+ = 0, indicating perfect knowledge of x_0 (i.e., no uncertainty).
Suppose that we don’t know x_0 exactly, which is the typical case.

Then, we must enter a different \hat{x}_0^+ and \Sigma_{x,0}^+ in the code.


% System's true initial state is x = [0;0]. But, what if we don't know that?
xhat = [0.25; -0.05];
xhatstore(:,1) = xhat;

% Assume that xhat is a 2-sigma sample from the true distribution of x(0).
SigmaX = diag(xhat/2).^2;
boundstore(:,1) = 3*sqrt(diag(SigmaX));

% Continue with standard KF code for the main simulation loop...
